promql:
topk(3,
    (
      (rate(container_network_receive_packets_dropped_total{node="k8s-node2", interface="eth0", namespace="obs"}[5m]) 
       / 
      rate(container_network_receive_packets_total{node="k8s-node2", interface="eth0", namespace="obs"}[5m])
     ) * 100
    ),
    by (pod)
)

topk(
  3,
  (
    container_cpu_usage_seconds_total
      {container!="POD", pod_name=~"ts-order-(service|order-other-service).*"}[1m]
      / 60           # Convert from total seconds to core-seconds/minute
  )
  > 0.002          # Filter condition for 1-minute CPU usage > 0.002 cores/second
  // Hypothetical predict_linear function:
  // predict_linear(container_cpu_usage_seconds_total[30m], 10*60)   # If it existed
)

label_replace(
  api_calls_total - 
    (
      range_over_time(api_calls_total[7d ago:1h]) 
        // Here, replace '7d ago:1h' with the actual time shift to represent the same hour a week ago.
        // Note that this is not possible with pure PromQL and might require additional processing.
    ),
  "endpoint", "$1", "endpoint", "(.*)"
)

histogram_quantile(0.5, 
   irate(traces_spanmetrics_latency_bucket{downstream_service='security-service', le='+Inf'}[5m])
) * 1000 # Convert from milliseconds to seconds

sort_desc(
  on(node) (
    node_filesystem_free_bytes
    * on(node, device) group_left(pod_labels) 
      kube_pod_info{pod_name=~"ts-voucher-service.*", namespace="default"} 
  )
)[0]

topk(3,
    (
        node_filesystem_usage_bytes{device="/dev/sdX", node=~".*"} 
        -
        node_filesystem_size_bytes{device="/dev/sdX", node=~".*"}
    ) / 
    node_filesystem_size_bytes{device="/dev/sdX", node=~".*"} * 100
)[5m:1m]
on(node) where label_has(node_pod_name, "app=ts-inside-payment-service")
and node_filesystem_size_bytes{device="/dev/sdX", node=~".*"} > 90 * 1024 * 1024 * 1024

max by (container_name) (
  rate(container_memory_max_usage_bytes[24h])
  * on (namespace,pod_name) group_left(container_name)
  container_labels{service="verification_code"}
)
max by (container_name) (
  rate(container_memory_max_usage_bytes[24h])
)

# Select fs_limit and fs_usage for containers of ts-payment-service on k8s-node2
container_fs_limit_bytes{container="ts-payment-service",node="k8s-node2"}
,
container_fs_usage_bytes{container="ts-payment-service",node="k8s-node2"}

# Calculate the free space on k8s-node2
node_filesystem_free_bytes{node="k8s-node2"}
# Calculate the usage percentage for ts-payment-service on k8s-node2
(container_fs_usage_bytes{container="ts-payment-service",node="k8s-node2"} 
/ 
container_fs_limit_bytes{container="ts-payment-service",node="k8s-node2"})
* 100

sum(container_memory_cache) by (pod_name)
sum(container_memory_cache) by (pod_name, service) [with_service_filter]
(sum(container_memory_cache) by (pod_name, service)) {service="verification-code"}

sum by (mode) (
  rate(node_cpu_seconds_total{node_ip=~"10.176.122.15[1-3]", cpu_cores>=16}[1m])
) / 
sum by () (
  rate(node_cpu_seconds_total{node_ip=~"10.176.122.15[1-3]", cpu_cores>=16}[1m])
)

current_count := node_sockstat_TCP_mem{service="gateway", state="mem"}
change_in_count := delta(current_count[24h])
current_count, change_in_count

(
  histogram_quantile(0.95, sum(rate(traces_service_graph_request_client_seconds_bucket{client="ts-basic-service", server="ts-route-service"}[60m])) BY (le))
  > 0.09
) AND (
  100 * sum(container_cpu_usage_seconds_total{container="ts-route-service", image!=""}) / sum(kube_pod_container_resource_limits{container="ts-route-service", resource="cpu"}) < 3
)
